{
  "sop_id": "SOP-019",
  "title": "Incident review & RCA",
  "steps": [
    {
      "step_id": "S1",
      "name": "Open the ticket and assign to yourself",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Lock down the incident record and set the severity",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Gather evidence: logs, photos, witness statements",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Reconstruct the timeline, find the root cause (5-Why or fishbone)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Assess the cost, downtime, and safety impact",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Define CAPA with owners and due dates",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Compile everything into the report and submit",
      "role": "Executor",
      "type": "work"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "always"
    },
    {
      "stage": "HOD",
      "condition": "major incidents"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Maintenance/Engineering",
      "item": "technical findings",
      "parallel_group": "P1"
    },
    {
      "dep_id": "D2",
      "provider": "HSE",
      "item": "safety assessment",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.85
}
